import React, { useState, useEffect, useCallback, useRef } from "react";
import { Helmet } from "react-helmet";
import * as Icons from "react-icons/bs";
import Select from "react-select";
import { useAuth } from "../AuthProvider";
import supabase from "../services/supabase-client";
import "../css/Frequencia.css";

const cleanCategoryName = (name: string | null | undefined): string => {
  if (!name) return "";
  const cleaned = name.replace(/^\d+(?:\.\d+)*[\s\-\.]*/, "").trim();
  return cleaned || name;
};

const getStoragePathFromUrl = (url: string | null | undefined): string | null => {
  if (!url) return null;
  const parts = url.split('/comprovantes/');
  if (parts.length > 1) {
    return parts[parts.length - 1];
  }
  return null;
};

function ContasPagarReceber() {
  const { isAdmin, user } = useAuth();

  const [categoriasDb, setCategoriasDb] = useState<any[]>([]);
  const [fornecedoresDb, setFornecedoresDb] = useState<any[]>([]);
  const [clientesDb, setClientesDb] = useState<any[]>([]);
  const [lancamentos, setLancamentos] = useState<any[]>([]);
  const [profilesMap, setProfilesMap] = useState<{[key: string]: string}>({});
  const [contasDb, setContasDb] = useState<any[]>([]);
  const [savingRow, setSavingRow] = useState(false);
  const [showNewModal, setShowNewModal] = useState(false);
  const [newTipo, setNewTipo] = useState<'entrada' | 'saida'>('entrada');
  const newModalRef = useRef<HTMLDialogElement>(null);
  const [limit, setLimit] = useState(500);
  const [totalCount, setTotalCount] = useState(0);
  const [loadingLancamentos, setLoadingLancamentos] = useState(false);
  const [loadError, setLoadError] = useState(false);
  const lancamentosRequestRef = useRef(0);

  useEffect(() => {
    if (!showNewModal) return;
    const dialog = newModalRef.current;
    const previousOverflow = document.body.style.overflow;
    dialog?.showModal();
    document.body.style.overflow = 'hidden';
    return () => {
      dialog?.close();
      document.body.style.overflow = previousOverflow;
    };
  }, [showNewModal]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editRowData, setEditRowData] = useState<any>({});
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [editRowFile, setEditRowFile] = useState<File | null>(null);

  const [confirmingLancamento, setConfirmingLancamento] = useState<any | null>(null);
  const [confirmData, setConfirmData] = useState<string>("");
  const [confirmValor, setConfirmValor] = useState<string>("");
  const [selectedConta, setSelectedConta] = useState<string>("");
  const [confirmingLoading, setConfirmingLoading] = useState(false);
  const [importingLoading, setImportingLoading] = useState(false);
  const [importModalOpen, setImportModalOpen] = useState(false);
  const [importMonth, setImportMonth] = useState("");

  const [filterData, setFilterData] = useState("");
  const [filterDescricao, setFilterDescricao] = useState("");
  const [filterFornecedor, setFilterFornecedor] = useState<string | null>(null);
  const [filterCategoria, setFilterCategoria] = useState<string | null>(null);
  const [filterTipo, setFilterTipo] = useState<string | null>(null);

  const getToday = () => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  const [newRow, setNewRow] = useState({
    data: getToday(),
    descricao: "",
    fornecedor_cliente: "",
    valor: "",
    categoria: "",
    is_recorrente: false
  });

  const selectStyles = {
    control: (base: any) => ({
      ...base,
      height: '54px',
      minHeight: '54px',
      borderRadius: '4px',
      borderColor: '#cbd5e1',
      fontSize: '1.4rem'
    }),
    valueContainer: (base: any) => ({
      ...base,
      padding: '0 8px'
    }),
    menu: (base: any) => ({
      ...base,
      width: '380px',
      maxWidth: 'calc(100vw - 24px)',
      textAlign: 'left' as const,
      fontSize: '15px'
    }),
    option: (base: any) => ({
      ...base,
      fontSize: '15px',
      lineHeight: 1.5,
      padding: '10px 12px',
      whiteSpace: 'normal' as const,
      overflowWrap: 'anywhere' as const
    }),
    groupHeading: (base: any) => ({ ...base, fontSize: '13px', fontWeight: 700 }),
    menuPortal: (base: any) => ({
      ...base,
      zIndex: 9999
    })
  };

  const modalSelectStyles = {
    ...selectStyles,
    menu: (base: any) => ({ ...base, position: 'absolute' as const, zIndex: 10, fontSize: '15px' })
  };

  const filterSelectStyles = {
    control: (base: any) => ({
      ...base,
      height: '38px',
      minHeight: '38px',
      minWidth: '120px',
      borderRadius: '4px',
      borderColor: '#cbd5e1',
      fontSize: '1.2rem'
    }),
    valueContainer: (base: any) => ({
      ...base,
      padding: '0 8px',
      height: '38px',
      minHeight: '38px',
      display: 'flex',
      alignItems: 'center'
    }),
    indicatorsContainer: (base: any) => ({
      ...base,
      height: '38px',
      minHeight: '38px'
    }),
    placeholder: (base: any) => ({
      ...base,
      color: '#94a3b8',
      fontSize: '1.2rem',
      fontWeight: 'normal',
      textTransform: 'none'
    }),
    singleValue: (base: any) => ({
      ...base,
      color: '#334155',
      fontSize: '1.2rem',
      fontWeight: 'normal'
    }),
    input: (base: any) => ({
      ...base,
      fontSize: '1.2rem',
      fontWeight: 'normal'
    }),
    menu: (base: any) => ({
      ...selectStyles.menu(base)
    }),
    option: (base: any) => ({
      ...selectStyles.option(base)
    }),
    groupHeading: selectStyles.groupHeading,
    menuPortal: (base: any) => ({
      ...base,
      zIndex: 9999
    })
  };

  const fornecedorOptions = fornecedoresDb.map(f => ({ value: f.nome, label: f.nome }));
  const clienteOptions = clientesDb.map(c => ({ value: c.nome, label: c.nome }));
  const pessoaOptions = [
    { label: 'Fornecedores', options: fornecedorOptions },
    { label: 'Clientes', options: clienteOptions }
  ];

  const getPessoaOptions = (valorStr: string) => {
    if (!valorStr) return pessoaOptions;
    const val = parseFloat(valorStr.replace(",", ".") || "0");
    if (val < 0) return [{ label: 'Fornecedores', options: fornecedorOptions }];
    if (val > 0) return [{ label: 'Clientes', options: clienteOptions }];
    return pessoaOptions;
  };

  const contaOptions = contasDb.map(c => {
    const label = [c.banco, c.agencia, c.conta_corrente].filter(Boolean).join(" - ");
    const displayLabel = c.descricao ? `${label} (${c.descricao})` : label;
    return { value: label, label: displayLabel };
  });

  const categoriaOptions = categoriasDb.filter(c => !c.parent_id).map(pai => ({
    label: pai.nome,
    options: categoriasDb.filter(sub => sub.parent_id === pai.id).map(sub => ({
      value: cleanCategoryName(sub.nome),
      label: sub.nome
    }))
  }));



  useEffect(() => {
    async function fetchData() {
      try {

        const { data: cData, error: cError } = await supabase
          .from("contas")
          .select("id, banco, agencia, conta_corrente, descricao")
          .eq("ativo", true)
          .order("banco", { ascending: true });

        if (!cError && cData) {
          setContasDb(cData);
        }

        const { data: catData, error: catError } = await supabase
          .from("categorias_financeiras")
          .select("id, nome, parent_id")
          .order("nome", { ascending: true });

        if (!catError && catData) {
          setCategoriasDb(catData);
        }

        const { data: fornData, error: fornError } = await supabase
          .from("fornecedores")
          .select("id, nome")
          .eq("ativo", true)
          .order("nome", { ascending: true });

        if (!fornError && fornData) {
          setFornecedoresDb(fornData);
        }

        const { data: cliData, error: cliError } = await supabase
          .from("clientes_food_service")
          .select("id, nome")
          .eq("ativo", true)
          .order("nome", { ascending: true });

        if (!cliError && cliData) {
          setClientesDb(cliData);
        }

        const { data: profilesData, error: profilesError } = await supabase
          .from("profiles")
          .select("id, name");

        if (!profilesError && profilesData) {
          const map: {[key: string]: string} = {};
          profilesData.forEach((p: any) => {
            map[p.id] = p.name || "";
          });
          setProfilesMap(map);
        }

        // fetchLancamentos will be handled by the useEffect below
      } catch (err) {
        console.error("Erro ao buscar dados iniciais:", err);
      }
    }
    fetchData();
  }, []);

  const fetchLancamentosRef = useRef<any>(null);
  const previousFiltersRef = useRef('');

  const fetchLancamentos = useCallback(async () => {
    fetchLancamentosRef.current = fetchLancamentos;
    const filtersKey = JSON.stringify([filterData, filterDescricao, filterFornecedor, filterCategoria, filterTipo, isAdmin]);
    const filtersChanged = previousFiltersRef.current !== filtersKey;
    previousFiltersRef.current = filtersKey;
    const currentLimit = filtersChanged ? 500 : limit;
    if (filtersChanged) setLimit(500);
    const requestId = ++lancamentosRequestRef.current;
    setLoadingLancamentos(true);
    setLoadError(false);
    try {
      let query = supabase
        .from("contas_pagar_receber")
        .select("*", { count: 'exact' })
        .order("data", { ascending: true })
        .order("created_at", { ascending: false })
        .order("id", { ascending: true });

      if (!isAdmin) {
        query = query.or('status_revisao.is.null,status_revisao.neq.admin_only');
      }

      if (filterData) query = query.eq('data', filterData);
      if (filterDescricao) query = query.ilike('descricao', `%${filterDescricao}%`);
      if (filterFornecedor) query = query.eq('fornecedor_cliente', filterFornecedor);
      if (filterCategoria) query = query.eq('categoria', filterCategoria);
      if (filterTipo === 'pagar') query = query.lt('valor', 0);
      if (filterTipo === 'receber') query = query.gte('valor', 0);

      const rows: any[] = [];
      let total = 0;
      let target = currentLimit;
      do {
        const { data, error, count } = await query.range(rows.length, Math.min(rows.length + 500, target) - 1);
        if (requestId !== lancamentosRequestRef.current) return;
        if (error) throw error;
        if (count !== null) {
          total = count;
          target = Math.min(currentLimit, count);
        }
        if (!data?.length) break;
        rows.push(...data);
      } while (rows.length < target);
      setLancamentos(rows);
      setTotalCount(total);
    } catch (err) {
      console.error("Erro ao buscar lançamentos:", err);
      if (requestId === lancamentosRequestRef.current) setLoadError(true);
    } finally {
      if (requestId === lancamentosRequestRef.current) setLoadingLancamentos(false);
    }
  }, [isAdmin, limit, filterData, filterDescricao, filterFornecedor, filterCategoria, filterTipo]);

  useEffect(() => {
    if (user) {
      fetchLancamentos();
    }
  }, [fetchLancamentos, user]);

  useEffect(() => {
    const channel = supabase.channel('realtime-lancamentos')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'contas_pagar_receber' },
        () => {
          if (fetchLancamentosRef.current) {
            fetchLancamentosRef.current();
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);



  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRow.descricao || !newRow.valor) {
      alert("Preencha descrição e valor.");
      return;
    }

    try {
      setSavingRow(true);
      const val = Math.abs(parseFloat(newRow.valor.replace(",", "."))) * (newTipo === 'saida' ? -1 : 1);

      let fileUrl = null;
      if (selectedFile) {
        const fileExt = selectedFile.name.split('.').pop();
        const fileName = `${Math.random().toString(36).substring(2, 15)}.${fileExt}`;
        const filePath = `comprovantes/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from('comprovantes')
          .upload(filePath, selectedFile);

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('comprovantes')
          .getPublicUrl(filePath);
        
        fileUrl = urlData.publicUrl;
      }

      const payload = {
        data: newRow.data,
        descricao: newRow.descricao,
        fornecedor_cliente: newRow.fornecedor_cliente || null,
        valor: val,
        categoria: newRow.categoria || null,
        user_id: user?.id,
        is_recorrente: newRow.is_recorrente,
        arquivo_url: fileUrl
      };

      const { error } = await supabase.from("contas_pagar_receber").insert([payload]);
      if (error) throw error;

      setNewRow({ data: getToday(), descricao: "", valor: "", fornecedor_cliente: "", categoria: "", is_recorrente: false });
      setNewTipo('entrada');
      setShowNewModal(false);
      setSelectedFile(null);
      
      const fileInput = document.getElementById("comprovante-upload-input") as HTMLInputElement;
      if (fileInput) fileInput.value = "";

      fetchLancamentos();
    } catch (err: any) {
      console.error("Erro ao salvar:", err);
      alert("Erro ao salvar lançamento: " + (err?.message || JSON.stringify(err)));
    } finally {
      setSavingRow(false);
    }
  };

  const handleSaveInline = async (id: string) => {
    if (!editRowData.descricao || !editRowData.valor) {
      alert("Preencha descrição e valor.");
      return;
    }

    try {
      setSavingRow(true);
      const originalRow = lancamentos.find(l => l.id === id);
      
      let fileUrl = originalRow?.arquivo_url || null;
      if (editRowFile) {
        // If there was an old file, delete it from storage!
        if (originalRow?.arquivo_url) {
          const oldPath = getStoragePathFromUrl(originalRow.arquivo_url);
          console.log("Substituindo anexo: excluindo do Storage:", oldPath);
          if (oldPath) {
            const { data: delData, error: delError } = await supabase.storage.from('comprovantes').remove([oldPath]);
            if (delError) {
              console.error("Erro ao excluir arquivo substituído:", delError);
            } else {
              console.log("Sucesso ao excluir arquivo substituído:", delData);
            }
          }
        }

        const fileExt = editRowFile.name.split('.').pop();
        const fileName = `${Math.random().toString(36).substring(2, 15)}.${fileExt}`;
        const filePath = `comprovantes/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from('comprovantes')
          .upload(filePath, editRowFile);

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('comprovantes')
          .getPublicUrl(filePath);
        
        fileUrl = urlData.publicUrl;
      }

      const diffs = [];
      if (originalRow) {
        if (originalRow.descricao !== editRowData.descricao) diffs.push(`Descrição`);
        if (originalRow.data !== editRowData.data) diffs.push(`Data`);
        if (parseFloat(originalRow.valor).toFixed(2) !== parseFloat(editRowData.valor.toString().replace(",", ".")).toFixed(2)) diffs.push(`Valor`);
        if (originalRow.arquivo_url !== fileUrl) diffs.push(`Arquivo`);
      }

      const hasChanges = diffs.length > 0;

      let val = parseFloat(editRowData.valor.toString().replace(",", "."));

      const payload: any = {
        data: editRowData.data,
        descricao: editRowData.descricao,
        fornecedor_cliente: editRowData.fornecedor_cliente || null,
        valor: val,
        categoria: editRowData.categoria || null,
        is_recorrente: editRowData.is_recorrente,
        arquivo_url: fileUrl
      };

      if (hasChanges) {
        payload.updated_at = new Date().toISOString();
      }

      const { error } = await supabase.from("contas_pagar_receber").update(payload).eq("id", id);
      if (error) throw error;

      setEditingId(null);
      setEditRowFile(null);
      fetchLancamentos();
    } catch (err: any) {
      console.error("Erro ao salvar edição:", err);
      alert("Erro ao atualizar lançamento: " + (err?.message || JSON.stringify(err)));
    } finally {
      setSavingRow(false);
    }
  };

  const handleEdit = (lancamento: any) => {
    setEditingId(lancamento.id);
    setEditRowFile(null);
    setEditRowData({
      data: lancamento.data,
      descricao: lancamento.descricao,
      fornecedor_cliente: lancamento.fornecedor_cliente || "",
      valor: lancamento.valor.toString(),
      categoria: lancamento.categoria || "",
      is_recorrente: lancamento.is_recorrente || false
    });
  };

  const handleDelete = async (id: string) => {
    const originalRow = lancamentos.find(l => l.id === id);
    if (window.confirm("Deseja excluir este lançamento?")) {
      try {
        const { error } = await supabase.from("contas_pagar_receber").delete().eq("id", id);
        if (error) throw error;

        // If it had an attached file, delete it from Storage too!
        if (originalRow?.arquivo_url) {
          const path = getStoragePathFromUrl(originalRow.arquivo_url);
          console.log("Excluindo lançamento: apagando do Storage:", path);
          if (path) {
            const { data: delData, error: delError } = await supabase.storage.from('comprovantes').remove([path]);
            if (delError) {
              console.error("Erro ao deletar arquivo do Storage:", delError);
              alert("Lançamento deletado, mas erro ao apagar anexo do Storage: " + delError.message);
            } else {
              console.log("Arquivo do Storage deletado com sucesso:", delData);
            }
          }
        }

        fetchLancamentos();
      } catch (err) {
        console.error("Erro ao excluir:", err);
        alert("Erro ao excluir lançamento.");
      }
    }
  }

  const handleUpdateReviewStatus = async (id: string, status: string | null) => {
    try {
      const { error } = await supabase.from("contas_pagar_receber").update({ status_revisao: status }).eq("id", id);
      if (error) throw error;
      fetchLancamentos();
    } catch (err: any) {
      console.error("Erro ao atualizar status:", err);
      alert("Erro ao atualizar status: " + (err?.message || JSON.stringify(err)));
    }
  };

  const handleConfirmar = async () => {
    if (!selectedConta) {
      alert("Selecione uma conta bancária para confirmar o lançamento.");
      return;
    }
    if (!confirmValor) {
      alert("Insira o valor confirmado.");
      return;
    }

    try {
      setConfirmingLoading(true);
      const parsedVal = parseFloat(confirmValor.replace(",", "."));
      if (isNaN(parsedVal)) {
        alert("Valor inválido.");
        return;
      }

      // Preserve the original sign (despesa is negative, receita is positive)
      const sign = confirmingLancamento.valor < 0 ? -1 : 1;
      const finalValor = parsedVal * sign;

      const payload = {
        data: confirmData,
        descricao: confirmingLancamento.descricao,
        fornecedor: confirmingLancamento.fornecedor_cliente,
        valor: finalValor,
        categoria: confirmingLancamento.categoria,
        conta: selectedConta,
        user_id: user?.id,
        status_revisao: confirmingLancamento.status_revisao || null
      };

      const { error: insertError } = await supabase.from("lancamentos_financeiros").insert([payload]);
      if (insertError) throw insertError;

      if (confirmingLancamento.is_recorrente) {
        const parts = confirmingLancamento.data.split('-');
        let nextMonth = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
        nextMonth.setMonth(nextMonth.getMonth() + 1);
        const nextDateStr = `${nextMonth.getFullYear()}-${String(nextMonth.getMonth() + 1).padStart(2, '0')}-${String(nextMonth.getDate()).padStart(2, '0')}`;
        
        const { error: updateError } = await supabase.from("contas_pagar_receber").update({ data: nextDateStr }).eq("id", confirmingLancamento.id);
        if (updateError) throw updateError;
      } else {
        const { error: deleteError } = await supabase.from("contas_pagar_receber").delete().eq("id", confirmingLancamento.id);
        if (deleteError) throw deleteError;
      }

      setConfirmingLancamento(null);
      setSelectedConta("");
      fetchLancamentos();
    } catch (err: any) {
      console.error("Erro ao confirmar:", err);
      alert("Erro ao confirmar lançamento: " + (err?.message || JSON.stringify(err)));
    } finally {
      setConfirmingLoading(false);
    }
  };

  const openImportModal = () => {
    const d = new Date();
    const currentYear = d.getFullYear();
    const currentMonth = String(d.getMonth() + 1).padStart(2, '0');
    setImportMonth(`${currentYear}-${currentMonth}`);
    setImportModalOpen(true);
  };

  const handleImportContasFixas = async () => {
    if (!importMonth) {
      alert("Selecione um mês válido.");
      return;
    }

    try {
      setImportingLoading(true);
      
      const { data: fixas, error: fixasError } = await supabase
        .from("contas_fixas")
        .select("*")
        .eq("ativo", true);
        
      if (fixasError) throw fixasError;
      if (!fixas || fixas.length === 0) {
        alert("Nenhuma conta fixa cadastrada.");
        setImportModalOpen(false);
        return;
      }

      const [yearStr, monthStr] = importMonth.split('-');
      const targetYear = parseInt(yearStr);
      const targetMonth = parseInt(monthStr);
      
      const firstDay = `${targetYear}-${String(targetMonth).padStart(2, '0')}-01`;
      const lastDay = new Date(targetYear, targetMonth, 0).getDate();
      const lastDayStr = `${targetYear}-${String(targetMonth).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      // Fetch existing records for this month to check duplicates
      const { data: existing, error: existingError } = await supabase
        .from("contas_pagar_receber")
        .select("data, descricao, valor")
        .gte("data", firstDay)
        .lte("data", lastDayStr);

      if (existingError) throw existingError;

      const payload = fixas.map(f => {
        const m = String(targetMonth).padStart(2, '0');
        const d = String(Math.min(f.dia_vencimento, lastDay)).padStart(2, '0'); // Evita dia 31 em mês de 30
        const dataVencimento = `${targetYear}-${m}-${d}`;

        return {
          data: dataVencimento,
          descricao: f.descricao,
          fornecedor_cliente: f.fornecedor_cliente,
          valor: f.valor,
          categoria: f.categoria,
          user_id: user?.id
        };
      });

      // Duplicates check
      let newPayload = payload;
      const duplicates = payload.filter(p => 
        existing?.some(e => e.data === p.data && e.descricao === p.descricao && e.valor === p.valor)
      );

      if (duplicates.length > 0) {
        const proceed = window.confirm(`Encontramos ${duplicates.length} conta(s) fixa(s) que já parecem ter sido importadas neste mês (mesma descrição, valor e data).\n\nDeseja pular as duplicadas e importar apenas as ${payload.length - duplicates.length} novas?\n\n(Clique em Cancelar para abortar toda a importação)`);
        
        if (!proceed) {
          setImportingLoading(false);
          return;
        }

        // Filter out duplicates
        newPayload = payload.filter(p => !duplicates.includes(p));
      }

      if (newPayload.length === 0) {
        alert("Nenhuma conta nova para importar neste mês.");
        setImportModalOpen(false);
        setImportingLoading(false);
        return;
      }

      const { error: insertError } = await supabase
        .from("contas_pagar_receber")
        .insert(newPayload);

      if (insertError) throw insertError;
      
      setImportModalOpen(false);
      fetchLancamentos();
    } catch (err: any) {
      console.error("Erro ao importar contas fixas:", err);
      alert("Erro ao importar: " + (err?.message || JSON.stringify(err)));
    } finally {
      setImportingLoading(false);
    }
  };

  return (
    <>
      <Helmet>
        <title>Contas a pagar e receber</title>
        <style>{`
          @keyframes pulse-red {
            0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
            70% { box-shadow: 0 0 0 6px rgba(239, 68, 68, 0); }
            100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
          }
        `}</style>
      </Helmet>

      <div className="frequencia-container accounts-payable-page">
        <div className="frequencia-header">
          <div className="frequencia-title-group" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%", flexWrap: "wrap", gap: "16px" }}>
            <div>
              <h1>Contas a pagar e receber</h1>
              <p>Registre contas a pagar e receber. Acompanhe os compromissos financeiros.</p>
            </div>
          </div>
        </div>

        <div className="freq-annual-summary-wrapper" style={{ margin: "20px auto", maxWidth: "100%", padding: "0 20px" }}>

          {showNewModal && <dialog
            ref={newModalRef}
            className="financial-new-modal"
            aria-labelledby="accounts-new-title"
            onCancel={(event) => { event.preventDefault(); if (!savingRow) setShowNewModal(false); }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
              <h3 id="accounts-new-title" style={{ margin: 0, color: "#334155", fontSize: "1.8rem", display: "flex", alignItems: "center", gap: "8px" }}>
                <Icons.BsPlusCircleFill style={{ color: "var(--primary-color)" }} />
                Novo Lançamento
              </h3>
              <button type="button" className="financial-modal-close" aria-label="Fechar" disabled={savingRow} onClick={() => setShowNewModal(false)}><Icons.BsX /></button>
            </div>

            <form onSubmit={handleSave} className="financial-new-form">

              <div style={{ flex: "2 1 200px" }}>
                <label style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Descrição</label>
                <input
                  type="text"
                  placeholder="Ex: Pagamento Fornecedor X"
                  autoFocus
                  value={newRow.descricao}
                  onChange={(e) => setNewRow({ ...newRow, descricao: e.target.value })}
                  style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #cbd5e1", height: "54px", fontSize: "1.4rem" }}
                  required
                />
              </div>

              <div>
                <label htmlFor="accounts-new-type" style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Tipo de lançamento</label>
                <select
                  id="accounts-new-type"
                  value={newTipo}
                  onChange={(e) => {
                    const tipo = e.target.value as 'entrada' | 'saida';
                    setNewTipo(tipo);
                    setNewRow(prev => ({ ...prev, fornecedor_cliente: '', valor: prev.valor ? (Math.abs(parseFloat(prev.valor.replace(',', '.'))) * (tipo === 'saida' ? -1 : 1)).toFixed(2) : '' }));
                  }}
                  style={{ width: "100%", padding: "8px", borderRadius: "4px", border: `1px solid ${newTipo === 'entrada' ? '#86efac' : '#fca5a5'}`, height: "54px", fontSize: "1.4rem", fontWeight: 600, background: newTipo === 'entrada' ? '#f0fdf4' : '#fef2f2', color: newTipo === 'entrada' ? '#15803d' : '#b91c1c' }}
                >
                  <option value="entrada" style={{ color: '#15803d', background: '#f0fdf4' }}>🟢 Entrada (+)</option>
                  <option value="saida" style={{ color: '#b91c1c', background: '#fef2f2' }}>🔴 Saída (−)</option>
                </select>
              </div>

              <div style={{ flex: "1 1 120px" }}>
                <label style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Data de Vencimento</label>
                <input
                  type="date"
                  value={newRow.data}
                  onChange={(e) => setNewRow({ ...newRow, data: e.target.value })}
                  style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #cbd5e1", textAlign: "center", height: "54px", fontSize: "1.4rem" }}
                  required
                />
              </div>

              <div style={{ flex: "1 1 120px" }}>
                <label style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Valor (R$)</label>
                <div style={{ position: "relative", display: "flex", alignItems: "center" }}>
                  <span style={{ position: "absolute", left: "12px", color: "#94a3b8", zIndex: 1, pointerEvents: "none", fontSize: "1.2rem", fontWeight: "bold" }}>R$</span>
                  <input
                    type="number"
                    step="0.01"
                    className="no-spinner"
                    placeholder="0.00"
                    value={newRow.valor}
                    onChange={(e) => {
                      const magnitude = e.target.value.replace(/^-/, '');
                      setNewRow({ ...newRow, valor: magnitude ? `${newTipo === 'saida' ? '-' : ''}${magnitude}` : '' });
                    }}
                    onBlur={(e) => {
                      if (e.target.value) {
                        setNewRow({ ...newRow, valor: parseFloat(e.target.value).toFixed(2) });
                      }
                    }}
                    style={{ width: "100%", padding: "8px 8px 8px 36px", borderRadius: "4px", border: "1px solid #cbd5e1", textAlign: "center", height: "54px", fontSize: "1.4rem" }}
                    required
                  />
                </div>
              </div>

              <div style={{ flex: "2 1 220px" }}>
                <label style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>{newTipo === 'entrada' ? 'Cliente' : 'Fornecedor'}</label>
                <Select
                  options={newTipo === 'entrada' ? clienteOptions : fornecedorOptions}
                  value={(newTipo === 'entrada' ? clienteOptions : fornecedorOptions).find(o => o.value === newRow.fornecedor_cliente) || null}
                  onChange={(option: any) => setNewRow({ ...newRow, fornecedor_cliente: option ? option.value : "" })}
                  placeholder={newTipo === 'entrada' ? 'Buscar Cliente...' : 'Buscar Fornecedor...'}
                  isClearable
                  styles={modalSelectStyles}
                  menuPlacement="auto"
                  maxMenuHeight={220}
                  menuShouldScrollIntoView={false}
                />
              </div>

              <div style={{ flex: "2 1 220px" }}>
                <label style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Categoria</label>
                <Select
                  options={categoriaOptions}
                  value={categoriaOptions.flatMap(g => g.options).find(o => o.value === newRow.categoria) || null}
                  onChange={(option: any) => setNewRow({ ...newRow, categoria: option ? option.value : "" })}
                  placeholder="Buscar Categoria..."
                  isClearable
                  styles={modalSelectStyles}
                  menuPlacement="auto"
                  maxMenuHeight={220}
                  menuShouldScrollIntoView={false}
                />
              </div>

              <div style={{ flex: "2 1 200px" }}>
                <label style={{ display: "block", fontSize: "1.3rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Anexo / Comprovante</label>
                <label 
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "8px",
                    padding: "0 12px",
                    borderRadius: "4px",
                    border: "1px dashed #cbd5e1",
                    backgroundColor: "#f8fafc",
                    color: "#64748b",
                    fontSize: "1.3rem",
                    cursor: "pointer",
                    height: "54px",
                    boxSizing: "border-box",
                    transition: "all 0.2s"
                  }}
                  onMouseEnter={(e) => { e.currentTarget.style.borderColor = "var(--primary-color)"; e.currentTarget.style.backgroundColor = "#fff"; }}
                  onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#cbd5e1"; e.currentTarget.style.backgroundColor = "#f8fafc"; }}
                >
                  <Icons.BsUpload style={{ fontSize: "1.6rem", color: "var(--primary-color)", flexShrink: 0 }} />
                  <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {selectedFile ? selectedFile.name : "Selecionar Arquivo..."}
                  </span>
                  <input
                    id="comprovante-upload-input"
                    type="file"
                    onChange={(e) => setSelectedFile(e.target.files?.[0] || null)}
                    style={{ display: "none" }}
                  />
                </label>
              </div>

              <div className="financial-modal-actions">
                <button type="button" className="financial-modal-cancel" disabled={savingRow} onClick={() => setShowNewModal(false)}>Cancelar</button>
                <button
                  type="submit"
                  disabled={savingRow}
                  style={{
                    height: "54px",
                    padding: "0",
                    backgroundColor: "var(--primary-color)",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    cursor: savingRow ? "not-allowed" : "pointer",
                    fontWeight: "bold",
                    fontSize: "1.4rem",
                    width: "180px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: "8px"
                  }}
                >
                  <Icons.BsCheckCircleFill /> {savingRow ? 'Salvando...' : 'Salvar lançamento'}
                </button>
              </div>
            </form>
          </dialog>}

          {/* Barra de Filtros foi movida para dentro da tabela */}
          <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '12px' }}>
            <button type="button" className="financial-add-button" onClick={() => { setEditingId(null); setShowNewModal(true); }}><Icons.BsPlusCircleFill /> Adicionar</button>
            <span style={{ fontSize: '1.2rem', color: '#64748b' }}>Clique em uma célula para editar</span>
            {isAdmin && <button type="button" className="financial-add-button" style={{ margin: 0 }} onClick={openImportModal}><Icons.BsCloudDownload /> Importar Contas Fixas</button>}
          </div>

          <div className="freq-table-wrapper financial-table-scroll" style={{ overflowX: "auto", boxShadow: "0 4px 6px rgba(0,0,0,0.05)", marginTop: "16px" }}>
            <table className="freq-table" style={{ minWidth: "1000px" }}>
              <thead>
                <tr>
                  <th style={{ width: "250px" }}>Descrição</th>
                  <th style={{ textAlign: "center", width: "80px" }}>Data de Vencimento</th>
                  <th style={{ textAlign: "center", width: "100px" }}>Status</th>
                  <th style={{ textAlign: "center", width: "120px" }}>Valor</th>
                  <th style={{ textAlign: "center", width: "150px" }}>Fornecedor / Cliente</th>
                  <th style={{ textAlign: "center", width: "150px" }}>Categoria</th>
                  <th style={{ textAlign: "center", width: "140px" }}>Tipo</th>
                  {isAdmin && <th style={{ textAlign: "center", width: "150px" }}>Usuário</th>}
                  <th style={{ textAlign: "center", width: "120px" }}>Ações</th>
                </tr>
                <tr style={{ backgroundColor: "#f8fafc", borderBottom: "2px solid #e2e8f0" }}>
                  <th style={{ padding: "8px" }}>
                    <input
                      type="text"
                      placeholder="Descrição..."
                      value={filterDescricao}
                      onChange={(e) => setFilterDescricao(e.target.value)}
                      style={{ width: "100%", height: "38px", padding: "6px 8px", borderRadius: "4px", border: "1px solid #cbd5e1", outline: "none", fontSize: "1.2rem", boxSizing: "border-box" }}
                    />
                  </th>
                  <th style={{ padding: "8px" }}>
                    <input
                      type="date"
                      value={filterData}
                      onChange={(e) => setFilterData(e.target.value)}
                      style={{ width: "100%", height: "38px", padding: "6px 8px", borderRadius: "4px", border: "1px solid #cbd5e1", outline: "none", fontSize: "1.2rem", boxSizing: "border-box" }}
                    />
                  </th>
                  <th></th>
                  <th></th>
                  <th style={{ padding: "8px" }}>
                    <Select
                      menuPortalTarget={document.body}
                      options={pessoaOptions}
                      value={filterFornecedor ? { value: filterFornecedor, label: filterFornecedor } : null}
                      onChange={(sel: any) => setFilterFornecedor(sel ? sel.value : null)}
                      placeholder="Fornecedor / Cliente..."
                      isClearable
                      styles={filterSelectStyles}
                    />
                  </th>
                  <th style={{ padding: "8px" }}>
                    <Select
                      menuPortalTarget={document.body}
                      options={categoriaOptions}
                      value={filterCategoria ? { value: filterCategoria, label: filterCategoria } : null}
                      onChange={(sel: any) => setFilterCategoria(sel ? sel.value : null)}
                      placeholder="Categoria..."
                      isClearable
                      styles={filterSelectStyles}
                    />
                  </th>
                  <th style={{ padding: "8px" }}>
                    <Select
                      menuPortalTarget={document.body}
                      options={[
                        { value: "pagar", label: "A Pagar" },
                        { value: "receber", label: "A Receber" }
                      ]}
                      value={filterTipo ? { value: filterTipo, label: filterTipo === "pagar" ? "A Pagar" : "A Receber" } : null}
                      onChange={(sel: any) => setFilterTipo(sel ? sel.value : null)}
                      placeholder="Tipo..."
                      isClearable
                      styles={filterSelectStyles}
                    />
                  </th>
                  {isAdmin && <th></th>}
                  <th style={{ padding: "8px", verticalAlign: "middle" }}>
                    <div style={{ display: "flex", gap: "4px", justifyContent: "center" }}>
                      <button
                        onClick={() => {
                          setFilterData("");
                          setFilterDescricao("");
                          setFilterFornecedor(null);
                          setFilterCategoria(null);
                          setFilterTipo(null);
                          fetchLancamentos();
                        }}
                        style={{
                          padding: "6px 8px",
                          backgroundColor: "#cbd5e1",
                          color: "#334155",
                          border: "none",
                          borderRadius: "4px",
                          cursor: "pointer",
                          fontSize: "1.2rem",
                          display: "inline-flex",
                          alignItems: "center",
                          justifyContent: "center"
                        }}
                        title="Limpar Filtros"
                      >
                        <Icons.BsXCircleFill />
                      </button>
                      <button
                        onClick={() => fetchLancamentos()}
                        style={{
                          padding: "6px 8px",
                          backgroundColor: "#f1f5f9",
                          color: "#475569",
                          border: "1px solid #cbd5e1",
                          borderRadius: "4px",
                          cursor: "pointer",
                          fontSize: "1.2rem",
                          display: "inline-flex",
                          alignItems: "center",
                          justifyContent: "center"
                        }}
                        title="Atualizar Dados"
                      >
                        <Icons.BsArrowClockwise />
                      </button>
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody>
                {(() => {
                  const lancamentosFiltrados = lancamentos;

                  if (lancamentosFiltrados.length === 0) {
                    return (
                      <tr>
                        <td colSpan={isAdmin ? 9 : 8} style={{ textAlign: "center", padding: "24px", color: "#94a3b8", fontSize: "1.3rem" }}>
                          Nenhum lançamento encontrado.
                        </td>
                      </tr>
                    );
                  }

                  const todayStr = getToday();
                  const todayDate = new Date(todayStr + "T00:00:00");
                  
                  const vencidos = lancamentosFiltrados.filter(l => l.data < todayStr);
                  const venceHoje = lancamentosFiltrados.filter(l => l.data === todayStr);
                  const vence7Dias = lancamentosFiltrados.filter(l => {
                    if (l.data <= todayStr) return false;
                    const lDate = new Date(l.data + "T00:00:00");
                    const diffTime = lDate.getTime() - todayDate.getTime();
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    return diffDays <= 7;
                  });
                  const futuros = lancamentosFiltrados.filter(l => {
                    if (l.data <= todayStr) return false;
                    const lDate = new Date(l.data + "T00:00:00");
                    const diffTime = lDate.getTime() - todayDate.getTime();
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    return diffDays > 7;
                  });

                  const renderRow = (l: any) => {
                    const diffMin = l.created_at ? (new Date().getTime() - new Date(l.created_at).getTime()) / (1000 * 60) : -1;
                    const diffEditMin = l.updated_at ? (new Date().getTime() - new Date(l.updated_at).getTime()) / (1000 * 60) : -1;
                    const isRowNew = l.created_at && diffMin >= 0 && diffMin < 60; // 1 hora de duração
                    const isRowEdited = l.updated_at && diffEditMin >= 0 && diffEditMin < 60; // 1 hora de duração

                    // Calculo do status
                    const hojeDate = new Date();
                    hojeDate.setHours(0,0,0,0);
                    const vencDate = new Date(l.data + 'T00:00:00');
                    const isAtrasado = vencDate < hojeDate;
                    
                    const statusText = isAtrasado ? "Atrasado" : "Pendente";
                    const statusBg = isAtrasado ? "#fee2e2" : "#fef08a";
                    const statusColor = isAtrasado ? "#b91c1c" : "#a16207";

                    return (
                      <tr key={l.id} className={editingId === l.id ? 'accounts-editing-row' : 'accounts-data-row'} onClick={(event) => {
                        const target = event.target as HTMLElement;
                        const cell = target.closest('td');
                        if (editingId !== l.id && cell && cell !== event.currentTarget.lastElementChild && !target.closest('button, a, input, select, label')) handleEdit(l);
                      }}>
                        {editingId === l.id ? (
                          <>
                            <td>
                              <input
                                type="text"
                                value={editRowData.descricao || ""}
                                onChange={(e) => setEditRowData({ ...editRowData, descricao: e.target.value })}
                                style={{ width: "100%", height: "32px", padding: "4px 8px", borderRadius: "4px", border: "1px solid #cbd5e1", boxSizing: "border-box", fontSize: "1.3rem", marginBottom: "4px" }}
                              />
                              <label 
                                style={{
                                  display: "inline-flex",
                                  alignItems: "center",
                                  gap: "6px",
                                  padding: "4px 8px",
                                  borderRadius: "4px",
                                  border: "1px dashed var(--primary-color)",
                                  backgroundColor: "#fffbeb",
                                  color: "var(--primary-color)",
                                  fontSize: "1.1rem",
                                  fontWeight: "bold",
                                  cursor: "pointer",
                                  transition: "all 0.2s",
                                  width: "100%",
                                  boxSizing: "border-box",
                                  overflow: "hidden"
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = "#fee2e2"; }}
                                onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = "#fffbeb"; }}
                              >
                                <Icons.BsUpload style={{ flexShrink: 0 }} />
                                <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                                  {editRowFile ? editRowFile.name : (editRowData.arquivo_url ? "Substituir Anexo" : "Adicionar Anexo")}
                                </span>
                                <input
                                  type="file"
                                  onChange={(e) => setEditRowFile(e.target.files?.[0] || null)}
                                  style={{ display: "none" }}
                                />
                              </label>
                            </td>
                            <td style={{ textAlign: "center" }}>
                              <input
                                type="date"
                                value={editRowData.data}
                                onChange={(e) => setEditRowData({ ...editRowData, data: e.target.value })}
                                style={{ width: "100%", height: "36px", padding: "4px", borderRadius: "4px", border: "1px solid #cbd5e1", textAlign: "center", boxSizing: "border-box", fontSize: "1.3rem" }}
                              />
                            </td>
                            <td style={{ textAlign: "center" }}>
                              {(() => {
                                const hojeDate = new Date();
                                hojeDate.setHours(0,0,0,0);
                                const vencDate = new Date(editRowData.data + 'T00:00:00');
                                const isAtrasado = vencDate < hojeDate;
                                const statusText = isAtrasado ? "Atrasado" : "Pendente";
                                const statusBg = isAtrasado ? "#fee2e2" : "#fef08a";
                                const statusColor = isAtrasado ? "#b91c1c" : "#a16207";
                                return (
                                  <span style={{
                                    background: statusBg,
                                    color: statusColor,
                                    padding: "4px 8px",
                                    borderRadius: "12px",
                                    fontWeight: "bold",
                                    fontSize: "1.1rem"
                                  }}>
                                    {statusText}
                                  </span>
                                );
                              })()}
                            </td>
                            <td style={{ textAlign: "center" }}>
                              <input
                                type="number"
                                step="0.01"
                                className="no-spinner"
                                value={editRowData.valor || ""}
                                onChange={(e) => setEditRowData({ ...editRowData, valor: e.target.value })}
                                onBlur={(e) => {
                                  if (e.target.value) {
                                    setEditRowData({ ...editRowData, valor: parseFloat(e.target.value).toFixed(2) });
                                  }
                                }}
                                style={{ width: "100%", height: "36px", padding: "4px 8px", borderRadius: "4px", border: "1px solid #cbd5e1", textAlign: "center", boxSizing: "border-box", fontSize: "1.3rem" }}
                              />
                            </td>
                            <td style={{ width: "20%" }}>
                              <Select
                                options={getPessoaOptions(editRowData.valor)}
                                value={pessoaOptions.flatMap(g => g.options).find(o => o.value === editRowData.fornecedor_cliente) || null}
                                onChange={(opt: any) => setEditRowData({ ...editRowData, fornecedor_cliente: opt ? opt.value : "" })}
                                placeholder="Selecionar..."
                                styles={filterSelectStyles}
                                menuPortalTarget={document.body}
                                isClearable
                              />
                            </td>
                            <td style={{ textAlign: "center" }}>
                              <Select
                                options={categoriaOptions}
                                value={categoriaOptions.flatMap(g => g.options).find(o => o.value === editRowData.categoria) || null}
                                onChange={(option: any) => setEditRowData({ ...editRowData, categoria: option ? option.value : "" })}
                                menuPortalTarget={document.body}
                                styles={{ ...selectStyles, control: (b: any) => ({ ...b, minHeight: '36px', height: '36px', fontSize: '1.3rem' }), valueContainer: (b: any) => ({ ...b, padding: '0 8px' }) }}
                              />
                            </td>
                            <td style={{ textAlign: "center" }}>
                              <span style={{
                                backgroundColor: parseFloat(editRowData.valor.toString().replace(",", ".") || "0") < 0 ? "#fee2e2" : "#dcfce7",
                                color: parseFloat(editRowData.valor.toString().replace(",", ".") || "0") < 0 ? "#b91c1c" : "#15803d",
                                padding: "4px 8px",
                                borderRadius: "12px",
                                fontWeight: "bold",
                                fontSize: "1.1rem",
                                display: "inline-block"
                              }}>
                                {parseFloat(editRowData.valor.toString().replace(",", ".") || "0") < 0 ? 'A Pagar' : 'A Receber'}
                              </span>
                            </td>
                            {isAdmin && <td></td>}
                            <td style={{ textAlign: "center", display: "flex", justifyContent: "center", gap: "8px" }}>
                              <button
                                onClick={() => handleSaveInline(l.id)}
                                style={{ backgroundColor: "transparent", border: "none", color: "#15803d", cursor: "pointer", fontSize: "1.6rem", padding: "4px", margin: 0 }}
                                title="Salvar"
                              >
                                <Icons.BsCheckCircleFill />
                              </button>
                              <button
                                onClick={() => setEditingId(null)}
                                style={{ backgroundColor: "transparent", border: "none", color: "#94a3b8", cursor: "pointer", fontSize: "1.6rem", padding: "4px", margin: 0 }}
                                title="Cancelar"
                              >
                                <Icons.BsXCircleFill />
                              </button>
                            </td>
                          </>
                        ) : (
                          <>
                            <td>
                              <div style={{ display: "flex", flexDirection: "column", gap: "6px", alignItems: "flex-start" }}>
                                {(l.status_revisao === 'admin_only' || isRowNew || isRowEdited || l.is_recorrente) && (
                                  <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
                                    {l.status_revisao === 'admin_only' && (
                                      <span style={{
                                        backgroundColor: "#3b82f6",
                                        color: "#ffffff",
                                        fontSize: "0.9rem",
                                        fontWeight: "bold",
                                        padding: "2px 6px",
                                        borderRadius: "4px",
                                        textTransform: "uppercase",
                                        lineHeight: "1.1",
                                        display: "inline-block",
                                        letterSpacing: "0.03em"
                                      }}>
                                        Somente Admin
                                      </span>
                                    )}
                                    {isRowNew && (
                                      <span style={{
                                        backgroundColor: "#10b981",
                                        color: "#ffffff",
                                        fontSize: "0.9rem",
                                        fontWeight: "bold",
                                        padding: "2px 6px",
                                        borderRadius: "4px",
                                        textTransform: "uppercase",
                                        lineHeight: "1.1",
                                        display: "inline-block",
                                        letterSpacing: "0.03em"
                                      }}>
                                        Novo
                                      </span>
                                    )}
                                    {isRowEdited && (
                                      <span style={{
                                        backgroundColor: "#f97316",
                                        color: "#ffffff",
                                        fontSize: "0.9rem",
                                        fontWeight: "bold",
                                        padding: "2px 6px",
                                        borderRadius: "4px",
                                        textTransform: "uppercase",
                                        lineHeight: "1.1",
                                        display: "inline-block",
                                        letterSpacing: "0.03em"
                                      }}>
                                        Editado
                                      </span>
                                    )}
                                    {l.is_recorrente && (
                                      <span style={{
                                        backgroundColor: "#8b5cf6",
                                        color: "#ffffff",
                                        fontSize: "0.9rem",
                                        fontWeight: "bold",
                                        padding: "2px 6px",
                                        borderRadius: "4px",
                                        textTransform: "uppercase",
                                        lineHeight: "1.1",
                                        display: "inline-flex",
                                        alignItems: "center",
                                        gap: "4px",
                                        letterSpacing: "0.03em"
                                      }}>
                                        <Icons.BsArrowRepeat /> Recorrente
                                      </span>
                                    )}
                                  </div>
                                )}
                                <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                                  <span>{l.descricao}</span>
                                  {l.arquivo_url && (
                                    <a
                                      href={l.arquivo_url}
                                      target="_blank"
                                      rel="noopener noreferrer"
                                      title="Ver Anexo / Comprovante"
                                      style={{
                                        display: "inline-flex",
                                        alignItems: "center",
                                        justifyContent: "center",
                                        color: "var(--primary-color)",
                                        fontSize: "1.6rem",
                                        padding: "4px",
                                        borderRadius: "4px",
                                        backgroundColor: "#f1f5f9",
                                        transition: "background 0.2s"
                                      }}
                                      onMouseEnter={(e) => e.currentTarget.style.backgroundColor = "#e2e8f0"}
                                      onMouseLeave={(e) => e.currentTarget.style.backgroundColor = "#f1f5f9"}
                                      onClick={(e) => e.stopPropagation()}
                                    >
                                      <Icons.BsPaperclip />
                                    </a>
                                  )}
                                </div>
                              </div>
                            </td>
                            <td style={{ textAlign: "center" }}>{new Date(l.data).toLocaleDateString("pt-BR", { timeZone: "UTC" })}</td>
                            <td style={{ textAlign: "center" }}>
                              <span style={{
                                background: statusBg,
                                color: statusColor,
                                padding: "4px 8px",
                                borderRadius: "12px",
                                fontWeight: "bold",
                                fontSize: "1.1rem"
                              }}>
                                {statusText}
                              </span>
                            </td>
                            <td style={{ textAlign: "center", fontWeight: "bold", color: l.valor < 0 ? "#ef4444" : "#334155", fontSize: "1.3rem" }}>
                              R$ {l.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </td>
                            <td style={{ textAlign: "center" }}>{l.fornecedor_cliente || "-"}</td>
                            <td style={{ textAlign: "center" }}>{l.categoria || "-"}</td>
                            <td style={{ textAlign: "center" }}>
                              <span style={{
                                background: l.valor >= 0 ? "#dcfce7" : "#fee2e2",
                                color: l.valor >= 0 ? "#15803d" : "#b91c1c",
                                padding: "4px 8px",
                                borderRadius: "12px",
                                fontWeight: "bold",
                                fontSize: "1.1rem"
                              }}>
                                {l.valor >= 0 ? "A Receber" : "A Pagar"}
                              </span>
                            </td>
                            {isAdmin && (
                              <td style={{ textAlign: "center" }}>
                                <span 
                                  title={l.created_at ? new Date(l.created_at).toLocaleString("pt-BR") : ""}
                                  style={{
                                    background: "#f1f5f9",
                                    border: "1px solid #cbd5e1",
                                    borderRadius: "8px",
                                    padding: "4px 12px",
                                    display: "inline-flex",
                                    alignItems: "center",
                                    gap: "6px",
                                    fontSize: "1.2rem",
                                    color: "#334155",
                                    cursor: "pointer"
                                  }}
                                >
                                  <Icons.BsPerson style={{ fontSize: "1.4rem", color: "#64748b" }} />
                                  {profilesMap[l.user_id] || "-"}
                                </span>
                              </td>
                            )}
                            <td style={{ textAlign: "center" }}>
                              <div style={{ display: "flex", gap: "8px", justifyContent: "center", alignItems: "center" }}>
                                {isAdmin && (
                                  l.status_revisao === 'admin_only' ? (
                                    <button
                                      onClick={() => handleUpdateReviewStatus(l.id, null)}
                                      title="Tornar Público (Todos visualizam)"
                                      style={{ padding: "4px 8px", fontSize: "1.1rem", color: "#3b82f6", backgroundColor: "transparent", border: "none", cursor: "pointer", display: "flex" }}
                                    >
                                      <Icons.BsShieldLockFill />
                                    </button>
                                  ) : (!l.status_revisao || l.status_revisao === 'none') && (
                                    <button
                                      onClick={() => handleUpdateReviewStatus(l.id, 'admin_only')}
                                      title="Restringir aos Admins (Apenas admins visualizam)"
                                      style={{ padding: "4px 8px", fontSize: "1.1rem", color: "#64748b", backgroundColor: "transparent", border: "none", cursor: "pointer", display: "flex" }}
                                    >
                                      <Icons.BsShieldLock />
                                    </button>
                                  )
                                )}
                                <button
                                  onClick={() => {
                                    setConfirmData(getToday());
                                    setConfirmingLancamento(l);
                                    setConfirmValor(Math.abs(l.valor).toString());
                                  }}
                                  className="nav-btn"
                                  title="Confirmar"
                                  style={{ padding: "4px 8px", fontSize: "0.9rem", color: "#10b981", borderColor: "#10b981" }}
                                >
                                  <Icons.BsCheck2Circle />
                                </button>
                                <button
                                  onClick={() => handleEdit(l)}
                                  className="nav-btn"
                                  title="Editar"
                                  style={{ padding: "4px 8px", fontSize: "0.9rem" }}
                                >
                                  <Icons.BsPencil />
                                </button>
                                <button
                                  onClick={() => handleDelete(l.id)}
                                  className="delete-record-btn"
                                  title="Excluir"
                                  style={{ margin: 0, padding: "4px 8px", fontSize: "0.9rem" }}
                                >
                                  <Icons.BsTrash />
                                </button>
                              </div>
                            </td>
                          </>
                        )}
                      </tr>
                    );
                  };

                  return (
                    <>
                      {vencidos.length > 0 && (
                        <>
                          <tr style={{ backgroundColor: "#fef2f2", borderBottom: "1px solid #fecaca", borderTop: "1px solid #fecaca" }}>
                            <td colSpan={isAdmin ? 9 : 8} style={{ textAlign: "center", padding: "10px", color: "#991b1b", fontWeight: "bold", fontSize: "1.15rem", letterSpacing: "0.05em", textTransform: "uppercase" }}>
                              Vencidos
                            </td>
                          </tr>
                          {vencidos.map(renderRow)}
                        </>
                      )}
                      {venceHoje.length > 0 && (
                        <>
                          <tr style={{ backgroundColor: "#fffbeb", borderBottom: "1px solid #fde68a", borderTop: "1px solid #fde68a" }}>
                            <td colSpan={isAdmin ? 9 : 8} style={{ textAlign: "center", padding: "10px", color: "#92400e", fontWeight: "bold", fontSize: "1.15rem", letterSpacing: "0.05em", textTransform: "uppercase" }}>
                              Vence Hoje
                            </td>
                          </tr>
                          {venceHoje.map(renderRow)}
                        </>
                      )}
                      {vence7Dias.length > 0 && (
                        <>
                          <tr style={{ backgroundColor: "#f0fdf4", borderBottom: "1px solid #bbf7d0", borderTop: "1px solid #bbf7d0" }}>
                            <td colSpan={isAdmin ? 9 : 8} style={{ textAlign: "center", padding: "10px", color: "#166534", fontWeight: "bold", fontSize: "1.15rem", letterSpacing: "0.05em", textTransform: "uppercase" }}>
                              Vence em 7 dias
                            </td>
                          </tr>
                          {vence7Dias.map(renderRow)}
                        </>
                      )}
                      {futuros.length > 0 && (
                        <>
                          <tr style={{ backgroundColor: "#f8fafc", borderBottom: "1px solid #e2e8f0", borderTop: "1px solid #e2e8f0" }}>
                            <td colSpan={isAdmin ? 9 : 8} style={{ textAlign: "center", padding: "10px", color: "#475569", fontWeight: "bold", fontSize: "1.15rem", letterSpacing: "0.05em", textTransform: "uppercase" }}>
                              Próximos
                            </td>
                          </tr>
                          {futuros.map(renderRow)}
                        </>
                      )}
                    </>
                  );
                })()}
              </tbody>
            </table>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px', margin: '24px 0' }} aria-busy={loadingLancamentos}>
            <span style={{ fontSize: '1.3rem', color: '#64748b' }} aria-live="polite">Mostrando <strong>{lancamentos.length}</strong> de <strong>{totalCount}</strong> totais{loadingLancamentos ? ' — Carregando...' : ''}</span>
            {loadError && <span role="alert" style={{ color: '#b91c1c' }}>Não foi possível carregar os lançamentos. <button type="button" onClick={() => fetchLancamentos()}>Tentar novamente</button></span>}
            {lancamentos.length < totalCount && <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: '10px' }}>
              <button type="button" disabled={loadingLancamentos} onClick={() => setLimit(prev => prev + 200)} style={{ padding: '12px 24px', border: '1px solid #cbd5e1', borderRadius: '12px', background: '#f8fafc', color: '#78593e', fontSize: '1.4rem', fontWeight: 'bold', cursor: loadingLancamentos ? 'wait' : 'pointer' }}>Carregar +200 linhas</button>
              <button type="button" disabled={loadingLancamentos} onClick={() => setLimit(Infinity)} style={{ padding: '12px 24px', border: 'none', borderRadius: '12px', background: 'var(--primary-color)', color: '#fff', fontSize: '1.4rem', fontWeight: 'bold', cursor: loadingLancamentos ? 'wait' : 'pointer' }}>Carregar tudo</button>
            </div>}
          </div>

        </div>
      </div>

      {confirmingLancamento && (
        <div style={{ position: "fixed", top: 0, left: 0, width: "100%", height: "100%", backgroundColor: "rgba(0,0,0,0.5)", display: "flex", justifyContent: "center", alignItems: "center", zIndex: 10000 }}>
          <div style={{ backgroundColor: "white", padding: "24px", borderRadius: "8px", width: "400px", maxWidth: "90%", boxShadow: "0 4px 6px rgba(0,0,0,0.1)" }}>
            <h3 style={{ marginTop: 0, marginBottom: "16px", color: "#334155", fontSize: "1.6rem", display: "flex", alignItems: "center", gap: "8px" }}>
              <Icons.BsCheck2Circle style={{ color: "#10b981" }} /> Confirmar {confirmingLancamento.valor < 0 ? "Pagamento" : "Recebimento"}
            </h3>
            <p style={{ marginBottom: "16px", color: "#64748b", fontSize: "1.2rem" }}>
              <strong>Descrição:</strong> {confirmingLancamento.descricao}
            </p>

            <div style={{ marginBottom: "16px" }}>
              <label style={{ display: "block", fontSize: "1.2rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Valor do Lançamento (R$)</label>
              <div style={{ position: "relative", display: "flex", alignItems: "center" }}>
                <span style={{ position: "absolute", left: "12px", color: "#94a3b8", zIndex: 1, pointerEvents: "none", fontSize: "1.2rem", fontWeight: "bold" }}>R$</span>
                <input
                  type="number"
                  step="0.01"
                  className="no-spinner"
                  placeholder="0.00"
                  value={confirmValor}
                  onChange={(e) => setConfirmValor(e.target.value)}
                  style={{ width: "100%", padding: "8px 8px 8px 36px", borderRadius: "4px", border: "1px solid #cbd5e1", fontSize: "1.2rem", boxSizing: "border-box" }}
                  required
                />
              </div>
            </div>

            <div style={{ marginBottom: "16px" }}>
              <label style={{ display: "block", fontSize: "1.2rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Data do Lançamento</label>
              <input
                type="date"
                value={confirmData}
                onChange={(e) => setConfirmData(e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #cbd5e1", fontSize: "1.2rem", boxSizing: "border-box" }}
              />
            </div>

            <div style={{ marginBottom: "24px" }}>
              <label style={{ display: "block", fontSize: "1.2rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Conta Bancária</label>
              <Select
                options={contaOptions}
                value={contaOptions.find(c => c.value === selectedConta) || null}
                onChange={(opt: any) => setSelectedConta(opt ? opt.value : "")}
                placeholder="Selecione a conta..."
                styles={{ ...filterSelectStyles, menuPortal: (b: any) => ({ ...b, zIndex: 10001 }) }}
                menuPortalTarget={document.body}
              />
            </div>

            <div style={{ display: "flex", gap: "12px", justifyContent: "flex-end" }}>
              <button
                onClick={() => setConfirmingLancamento(null)}
                style={{ padding: "8px 16px", borderRadius: "4px", border: "1px solid #cbd5e1", backgroundColor: "white", color: "#64748b", cursor: "pointer", fontSize: "1.2rem", fontWeight: "bold" }}
              >
                Cancelar
              </button>
              <button
                onClick={handleConfirmar}
                disabled={confirmingLoading}
                style={{ padding: "8px 16px", borderRadius: "4px", border: "none", backgroundColor: "#10b981", color: "white", cursor: confirmingLoading ? "not-allowed" : "pointer", fontSize: "1.2rem", fontWeight: "bold" }}
              >
                {confirmingLoading ? "Confirmando..." : "Confirmar"}
              </button>
            </div>
          </div>
        </div>
      )}

      {importModalOpen && (
        <div style={{ position: "fixed", top: 0, left: 0, width: "100%", height: "100%", backgroundColor: "rgba(0,0,0,0.5)", display: "flex", justifyContent: "center", alignItems: "center", zIndex: 10000 }}>
          <div style={{ backgroundColor: "white", padding: "24px", borderRadius: "8px", width: "400px", maxWidth: "90%", boxShadow: "0 4px 6px rgba(0,0,0,0.1)" }}>
            <h3 style={{ marginTop: 0, marginBottom: "16px", color: "#334155", fontSize: "1.6rem", display: "flex", alignItems: "center", gap: "8px" }}>
              <Icons.BsCloudDownload style={{ color: "var(--primary-color)" }} /> Importar Contas Fixas
            </h3>
            <p style={{ marginBottom: "16px", color: "#64748b", fontSize: "1.2rem" }}>
              Selecione o mês para qual deseja importar os lançamentos. O sistema criará novas contas a pagar/receber utilizando os dias de vencimento configurados nas suas contas fixas.
            </p>

            <div style={{ marginBottom: "24px" }}>
              <label style={{ display: "block", fontSize: "1.2rem", color: "#64748b", marginBottom: "4px", fontWeight: "bold" }}>Mês de Importação</label>
              <input
                type="month"
                value={importMonth}
                onChange={(e) => setImportMonth(e.target.value)}
                style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #cbd5e1", fontSize: "1.4rem", boxSizing: "border-box" }}
              />
            </div>

            <div style={{ display: "flex", gap: "12px", justifyContent: "flex-end" }}>
              <button
                onClick={() => setImportModalOpen(false)}
                style={{ padding: "8px 16px", borderRadius: "4px", border: "1px solid #cbd5e1", backgroundColor: "white", color: "#64748b", cursor: "pointer", fontSize: "1.2rem", fontWeight: "bold" }}
              >
                Cancelar
              </button>
              <button
                onClick={handleImportContasFixas}
                disabled={importingLoading}
                style={{ padding: "8px 16px", borderRadius: "4px", border: "none", backgroundColor: "var(--primary-color)", color: "white", cursor: importingLoading ? "not-allowed" : "pointer", fontSize: "1.2rem", fontWeight: "bold", display: "flex", alignItems: "center", gap: "8px" }}
              >
                {importingLoading ? "Importando..." : "Importar"}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
export default ContasPagarReceber;
